var cache = map[string][]byte{}

func firstLine(data []byte) []byte {
    i := bytes.IndexByte(data, '\n')
    if i < 0 {
        return data
    }
    return data[:i]
}

func remember(name string, data []byte) {
    cache[name] = firstLine(data)
}

