func header(big []byte) []byte {
    h := make([]byte, 10)
    copy(h, big[:10])
    return h // или: return bytes.Clone(big[:10])
}

func window(data []int64, from, to int) []int64 {
    out := make([]int64, to-from)
    copy(out, data[from:to])
    return out
}
